'use strict'

const { Query } = require('./query.js')

function Postgres () {
  const options = {
    database: 'postgres',
    host: ['localhost'],
    port: [5432],
    user: 'postgres',
  }

  function * handler (query) {
    yield query
  }

  function dispatch (query) {
    function * handler (query) {
      yield query
    }

    return handler(query)
  }

  return [handler(new Query()), dispatch(new Query())]
}

module.exports = Postgres
